-- KargaTrack database schema for Supabase.
-- Run this once in your Supabase project: Dashboard → SQL Editor → New query → paste → Run.
-- Safe to run again (uses IF NOT EXISTS / ON CONFLICT).
--
-- Every row belongs to the signed-in user (user_id), and Row Level Security
-- makes sure each account can only see and change its own data.
-- Ids are generated by the app so it can work offline and upload later.

-- ---------- Tables ----------
create table if not exists public.groups (
  user_id    uuid not null default auth.uid() references auth.users on delete cascade,
  id         text not null,
  name       text not null,
  emoji      text not null default '📦',
  archived   boolean not null default false,
  created_at bigint not null default (extract(epoch from now()) * 1000)::bigint,
  primary key (user_id, id)
);

create table if not exists public.items (
  user_id    uuid not null default auth.uid() references auth.users on delete cascade,
  id         text not null,
  group_id   text not null,
  name       text not null,
  price      numeric not null default 0,   -- your price to the vendor
  srp        numeric not null default 0,   -- vendor's selling price
  image      text,                          -- picture path, e.g. /items/thumbs/egg.webp ('' = none)
  archived   boolean not null default false,
  created_at bigint not null default (extract(epoch from now()) * 1000)::bigint,
  primary key (user_id, id)
);

create table if not exists public.vendors (
  user_id    uuid not null default auth.uid() references auth.users on delete cascade,
  id         text not null,
  name       text not null,
  phone      text,
  photo_url  text,
  archived   boolean not null default false,
  created_at bigint not null default (extract(epoch from now()) * 1000)::bigint,
  primary key (user_id, id)
);

create table if not exists public.transactions (
  user_id     uuid not null default auth.uid() references auth.users on delete cascade,
  id          text not null,
  group_id    text not null,
  vendor_id   text not null,
  date        date not null,
  time        text,
  -- [{ itemId, name, price, srp, qty, returned }] — prices are copied in so old records never change
  lines       jsonb not null default '[]'::jsonb,
  status      text not null default 'out' check (status in ('out', 'returned')),
  returned_at bigint,
  paid        boolean,
  paid_at     bigint,
  created_at  bigint not null default (extract(epoch from now()) * 1000)::bigint,
  primary key (user_id, id)
);

alter table public.items add column if not exists image text;

create index if not exists transactions_user_date_idx on public.transactions (user_id, date);

-- ---------- Row Level Security ----------
alter table public.groups       enable row level security;
alter table public.items        enable row level security;
alter table public.vendors      enable row level security;
alter table public.transactions enable row level security;

drop policy if exists "own groups" on public.groups;
create policy "own groups" on public.groups for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own items" on public.items;
create policy "own items" on public.items for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own vendors" on public.vendors;
create policy "own vendors" on public.vendors for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

drop policy if exists "own transactions" on public.transactions;
create policy "own transactions" on public.transactions for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- ---------- Vendor photos (Storage) ----------
-- Public bucket: photos are viewable by anyone who has the (random, unguessable) link.
-- Only the owner can upload, replace or delete files in their own folder: <user_id>/...
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('vendor-photos', 'vendor-photos', true, 1048576, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do nothing;

drop policy if exists "vendor photos insert own" on storage.objects;
create policy "vendor photos insert own" on storage.objects for insert to authenticated
  with check (bucket_id = 'vendor-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists "vendor photos update own" on storage.objects;
create policy "vendor photos update own" on storage.objects for update to authenticated
  using (bucket_id = 'vendor-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

drop policy if exists "vendor photos delete own" on storage.objects;
create policy "vendor photos delete own" on storage.objects for delete to authenticated
  using (bucket_id = 'vendor-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
